/* Enterprise workbench presentation, based on the local APX reference layouts. */
const UI={curve:'power',forecast:'load',allRows:false,help:false};
Object.assign(colors,{load:'#1677ff',pv:'#1cad78',grid:'#ff9b40',soc:'#8363dd',charge:'#1677ff',discharge:'#1cad78',actual:'#9ca8b8'});
const businessNav=[['overview','运行总览'],['forecast','负荷与光伏预测'],['parameters','碳因子与设备参数'],['dispatch','日前调度方案'],['fault','故障恢复管理'],['reports','方案与报告管理']];
function ico(type){const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',chart:'<path d="M4 4v16h17M8 15l4-5 4 3 5-8"/>',bolt:'<path d="M14 2L5 14h7l-2 8 9-12h-7z"/>',file:'<path d="M14 3H5v18h14V8zM14 3v6h5M8 13h8M8 17h6"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',folder:'<path d="M3 7V5h7l2 3h9v12H3z"/>',alert:'<path d="M12 3L2 21h20zM12 9v5m0 3v1"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 8a8 8 0 0114-2l1 3M4 15l1 3a8 8 0 0014-2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="M15 15l6 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0116 0v2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',check:'<path d="M4 12l5 5L20 6"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[type]||paths.folder}</svg>`}
function render(){
 const title=businessNav.find(n=>n[0]===S.page)?.[1]||'日前调度方案';
 $('#app').innerHTML=`<div class="business-shell"><header class="system-header"><div class="system-brand"><b>Energy<span>Ops</span></b><i></i><span>园区能源管理系统</span></div><div class="header-actions"><span class="env-tag">模拟环境</span><span class="header-region">科广校园　⌄</span><span class="usericon">${ico('user')}</span><span>演示用户</span></div></header><aside class="primary-rail">${[['grid','园区总览','overview'],['chart','能源预测','forecast'],['bolt','运行调度','dispatch'],['alert','故障管理','fault'],['file','报表管理','reports']].map(a=>`<button title="${a[1]}" aria-label="${a[1]}" class="rail-item ${S.page===a[2]||a[2]==='dispatch'&&S.page==='parameters'?'active':''}" onclick="go('${a[2]}')">${ico(a[0])}<span>${a[1]}</span></button>`).join('')}<button class="rail-item rail-bottom" title="模块说明" aria-label="模块说明" onclick="showTeam()">${ico('settings')}<span>模块说明</span></button></aside><aside class="side-menu"><h2>能源运行管理</h2><div class="menu-section">业务管理</div>${businessNav.map((a,i)=>`<button class="menu-item ${S.page===a[0]?'active':''}" onclick="go('${a[0]}')" aria-label="${a[1]}">${ico(i===0?'grid':i===4?'alert':'folder')}<span>${a[1]}</span></button>`).join('')}<div class="menu-section">演示工具</div><button class="menu-item secondary" onclick="startTour('normal')">${ico('chart')}<span>正常调度流程</span></button><button class="menu-item secondary" onclick="startTour('fault')">${ico('alert')}<span>故障恢复流程</span></button><button class="menu-item secondary" onclick="showTeam()">${ico('info')}<span>团队分工与接口</span></button><div class="side-bottom"><span class="statusdot"></span>浏览器本地计算<br><span>时区：Asia/Shanghai</span></div></aside><main class="main"><div class="page-tabs"><span class="tab-home" onclick="go('overview')">${ico('grid')}</span><button class="page-tab active">${title}</button><div class="tab-tools">${btn('重置演示',"resetDemo()",'text-btn')}${btn('模块说明',"showTeam()",'text-btn')}</div></div><div class="content">${S.tour?tourBanner():''}${({overview,forecast,parameters,dispatch,fault,reports})[S.page]()}<footer class="system-footer">数据类型：模拟　｜　时间粒度：1小时　｜　仅用于方案仿真与演示，不下发设备指令</footer></div></main></div>`;
}
function queryBar(extra='',run=false){return `<section class="card query-card"><div class="filter-fields"><div class="field"><label for="q-park">园区名称</label><select id="q-park"><option>科广校园（演示）</option></select></div><div class="field"><label for="day">运行日期</label><input id="day" type="date" value="${S.date}"></div><div class="field"><label for="weather">运行场景</label><select id="weather"><option value="sunny" ${S.scenario==='sunny'?'selected':''}>晴天</option><option value="cloudy" ${S.scenario==='cloudy'?'selected':''}>多云</option></select></div><div class="field"><label>数据来源</label><div class="readonly">模拟数据</div></div><div class="field"><label>数据版本</label><div class="readonly">DEMO-D${S.dataVersion}</div></div>${extra}</div><div class="query-actions"><div class="actions">${btn(ico('search')+'查询',"applyFilters()",'primary')}${btn('重置条件',"resetFilters()")}</div><div class="actions">${run?btn('输入检查',"showEvidence('data')")+btn(ico('bolt')+'生成调度方案',"generateFromForm()",'primary'):btn('数据详情',"showEvidence('data')")}</div></div></section>`}
function resetFilters(){change('scenario','sunny')}
function kpi(label,value,unit,note){return `<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}<span class="unit">${unit}</span></div><div class="kpi-note">${note}</div></div>`}
function overview(){const p=plan();return `${queryBar()}<div class="kpis overview-stats">${kpi('用电量',fmt(data.load.reduce((a,b)=>a+b,0),1),'kWh','模拟负荷 · 24个时段')}${kpi('光伏发电量',fmt(data.pv.reduce((a,b)=>a+b,0),1),'kWh','模拟发电数据')}${kpi('储能容量',fmt(S.capacity,0),'kWh',`额定功率 ${S.power} kW`)}${kpi('已生成方案',S.records.length,'份',S.current?'当前方案 '+S.current.id:'暂无计算记录')}</div><div class="grid2 overview-grid">${panel('负荷与光伏曲线',chart([{name:'负荷',values:data.load,color:colors.load},{name:'光伏',values:data.pv,color:colors.pv}],'kW',230),`<span class="sub">${S.date}　00:00—23:00</span>`)}${panel('设备运行信息',`<div class="tablewrap"><table><thead><tr><th>设备</th><th>参数</th><th>状态</th></tr></thead><tbody><tr><td>光伏系统</td><td>150 kWp</td><td>${badge('可用')}</td></tr><tr><td>储能系统</td><td>${S.capacity} kWh / ${S.power} kW</td><td>${badge(S.fault&&S.fault.feedback!=='full'?'事件处理中':'可用',S.fault?'warn':'')}</td></tr><tr><td>园区变压器</td><td>250 kW 有功限额</td><td>${badge('参数已配置')}</td></tr></tbody></table></div><div class="note-line">模拟拓扑与参数，非现场设备监测。</div>`)}</div>${panel('业务处理',`<div class="tablewrap"><table><thead><tr><th>业务事项</th><th>处理内容</th><th>关联记录</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>日前调度</td><td>基于负荷、光伏、电价与碳因子生成方案</td><td>${S.current?.id||'—'}</td><td>${badge(S.current?'已计算':'待计算',S.current?'':'warn')}</td><td>${btn('进入调度',"go('dispatch')",'link-btn')}</td></tr><tr><td>故障恢复</td><td>诊断、恢复反馈、状态更新与重规划</td><td>${S.fault?'EVT-001':'—'}</td><td>${badge(S.fault?.newId?'已重规划':S.fault?'处理中':'暂无事件',S.fault&&!S.fault.newId?'warn':'')}</td><td>${btn('事件管理',"go('fault')",'link-btn')}</td></tr><tr><td>方案报告</td><td>查看历史记录、复算依据与导出报告</td><td>${S.records.length} 份方案</td><td>—</td><td>${btn('查看记录',"go('reports')",'link-btn')}</td></tr></tbody></table></div>`)}<div class="module-strip"><span>专业模块</span>${[['预测','韦佳伶','forecast'],['碳因子与设备','凌俊楷','parameters'],['调度与集成','梁紫昱、凌俊楷','dispatch'],['电网与恢复','高翰林','fault']].map(a=>`<button onclick="go('${a[2]}')">${a[0]} <span>${a[1]}</span></button>`).join('')}</div>`}
function dispatch(){const p=plan(),ps=S.current?.alternatives||draft,base=ps[0],cfg=currentConfig(),v=Engine.verify(p);return `${queryBar(`<div class="field"><label for="objective">优化目标</label><select id="objective">${[['economic','经济优先'],['green','低碳优先'],['balanced','成本约束低碳']].map(a=>`<option value="${a[0]}" ${S.objective===a[0]?'selected':''}>${a[1]}</option>`).join('')}</select></div>`,true)}<section class="card scheme-card"><div class="cardhead"><h3>调度方案</h3><div class="actions"><span class="sub">${S.current?'当前：'+S.current.id:'待计算预览'}</span>${btn('设备参数',"go('parameters')",'small')}${btn('计算依据',"showTeam()",'small')}</div></div><div class="scheme-list">${ps.map((r,i)=>`<div class="scheme-row ${p.key===r.key?'selected':''}"><div class="scheme-name"><span class="scheme-letter scheme-${i}">方案${String.fromCharCode(65+i)}</span><strong>${r.name}</strong>${r.key==='balanced'?'<span class="recommend">成本受限</span>':''}</div><div><label>购电费用</label><b>${fmt(r.cost,2)} <small>元</small></b></div><div><label>购电碳排</label><b>${fmt(r.carbon,2)} <small>kgCO₂</small></b></div><div><label>费用增幅</label><b>${fmt((r.cost/base.cost-1)*100,2)}%</b></div><div><label>预算校核</label>${badge(r.cost<=base.cost*(1+cfg.budget/100)+1e-6?'满足':'超出预算',r.cost<=base.cost*(1+cfg.budget/100)+1e-6?'':'warn')}</div><div class="actions">${btn(p.key===r.key?'当前方案':'查看',`choose('${r.key}')`,'small outline-blue')}${btn('导出',`exportAlternative('${r.key}')`,'small',!S.current)}</div></div>`).join('')}</div><div class="scheme-foot"><span>比较口径：同一输入及设备状态；末端能量差单独列示。经济基准为候选集中最低费用。</span><label for="budget">费用增幅上限 <input id="budget" type="number" min="0" max="30" value="${S.budget}" onchange="change('budget',this.value)"> %</label></div></section>${S.missing?'<div class="notice error">碳因子缺失，方案生成已阻断。请恢复输入后重新计算。</div>':''}<section class="card dispatch-curves"><div class="cardhead"><h3>调度曲线与时段数据</h3><div class="actions"><span class="sub">储能 ${cfg.capacity} kWh / ${cfg.power} kW</span>${btn('校核详情',"showEvidence('verification')",'small',!S.current)}${btn('导出当前方案',"exportReport()",'small',!S.current)}</div></div><div class="tabline"><div class="tabs">${[['power','功率计划'],['battery','储能充放电'],['soc','SOC曲线']].map(a=>`<button class="tab ${UI.curve===a[0]?'active':''}" onclick="UI.curve='${a[0]}';render()">${a[1]}</button>`).join('')}</div><span class="sub">${S.current?S.current.id+' · '+S.current.stateLabel:'预览数据，尚未生成记录'}</span></div><div class="dispatch-body"><div class="table-chart"><div class="hour-table"><table><thead><tr><th>时段</th><th>${UI.curve==='soc'?'SOC(%)':UI.curve==='battery'?'充电(kW)':'购电(kW)'}</th><th>${UI.curve==='soc'?'能量(kWh)':UI.curve==='battery'?'放电(kW)':'负荷(kW)'}</th></tr></thead><tbody>${p.rows.slice(0,UI.allRows?24:8).map(r=>`<tr class="${S.hour===r.h?'selected':''}" onclick="selectHour(${r.h})"><td>${String(r.h).padStart(2,'0')}:00</td><td>${fmt(UI.curve==='soc'?r.soc:UI.curve==='battery'?r.charge:r.grid,2)}</td><td>${fmt(UI.curve==='soc'?r.energy:UI.curve==='battery'?r.discharge:r.load,2)}</td></tr>`).join('')}</tbody></table><button class="table-expand" onclick="UI.allRows=!UI.allRows;render()">${UI.allRows?'收起':'展开全部24个时段'}　⌄</button></div><div class="curve-main">${UI.curve==='power'?chart([{name:'购电功率',values:p.rows.map(r=>r.grid),color:colors.load},{name:'光伏功率',values:p.rows.map(r=>r.pv),color:colors.pv},{name:'负荷功率',values:p.rows.map(r=>r.load),color:'#a6afbd',dash:true}],'kW',245):UI.curve==='battery'?chart([{name:'充电功率',values:p.rows.map(r=>r.charge),color:colors.charge},{name:'放电功率',values:p.rows.map(r=>r.discharge),color:colors.discharge}],'kW',245):chart([{name:'SOC',values:p.rows.map(r=>r.soc),color:colors.soc}],'%',245)}<div class="hour-detail"><b>${String(S.hour).padStart(2,'0')}:00</b><span>购电 ${fmt(p.rows[S.hour].grid,2)} kW</span><span>SOC ${fmt(p.rows[S.hour].soc,2)}%</span><span>电价 ${fmt(p.rows[S.hour].price,2)} 元/kWh</span></div></div></div><aside class="strategy"><h4>策略说明 / 校核结果</h4>${strategyItem('blue','费用与碳排',`费用 ${fmt((p.cost/base.cost-1)*100,2)}%；碳排 ${fmt((p.carbon/base.carbon-1)*100,2)}%。相对同状态经济基准。`)}${strategyItem('green','设备约束',`初始SOC 50%；终态 ${fmt(p.rows[23].soc,2)}%；功率上限 ${cfg.power} kW。`)}${strategyItem('blue','独立复算',S.current?`${v.ok?'通过':'失败'}：功率平衡、能量递推、SOC及指标复算。`:'待计算，生成方案后保存复算结果。')}${strategyItem('orange','电网校核范围','仅250 kW有功限额筛查，未执行AC潮流。')}<button class="strategy-link" onclick="openExplanation()">查看完整说明</button></aside></div></section><div class="grid3 bottom-metrics">${panel('费用约束',`<div class="metric"><strong>${fmt((p.cost/base.cost-1)*100,2)}<small>%</small></strong>${badge('上限 '+cfg.budget+'%',p.cost>base.cost*(1+cfg.budget/100)+1e-6?'warn':'')}<span>基准费用 ${fmt(base.cost,2)} 元</span></div>`)}${panel('运行指标',`<div class="metric"><strong>${fmt(p.curtail,2)}<small>kWh</small></strong><span>弃光电量　｜　终态能量差 ${fmt(p.terminal-p.initial,2)} kWh</span></div>`)}${panel('方案审阅',`<div class="metric"><span>${S.current?.reviewed?badge('已审阅'):badge('待审阅','warn')}</span>${btn('标记审阅',"reviewCurrent()",'small',!S.current)}${btn('故障恢复',"go('fault')",'small')}</div>`)}</div><div class="note-line">${btn(S.missing?'恢复碳因子':'缺失数据演示',"S.missing=!S.missing;S.current=null;render()",'text-btn')}<span>算法：规则启发式候选扫描；数据与结果均为模拟，不代表真实模型效果。</span></div>`}
function strategyItem(color,title,text){return `<div class="strategy-item"><span class="strategy-dot ${color}"></span><div><b>${title}</b><p>${text}</p></div></div>`}
function exportAlternative(key){if(!S.current)return;const r={...S.current,plan:S.current.alternatives.find(p=>p.key===key)};download(r.id+'-'+r.plan.name+'-方案报告.md',reportText(r))}
function openExplanation(){const p=plan(),ps=S.current?.alternatives||draft;modal('方案说明',`<table><tbody><tr><td>当前方案</td><td>${S.current?.id||'预览'} / ${p.name}</td></tr><tr><td>计算方式</td><td>81组电价与碳因子权重候选扫描，不保证全局最优。</td></tr><tr><td>充放电依据</td><td>加权分数、SOC范围、充放电功率及末端能量恢复约束。</td></tr><tr><td>经济基准</td><td>同一输入及设备状态下，候选集中最低费用 ${fmt(ps[0].cost,2)} 元。</td></tr><tr><td>碳排边界</td><td>购电量乘以分时碳因子，不含设备全生命周期。</td></tr><tr><td>检查范围</td><td>独立数值复算与250kW有功限额筛查，不含真实潮流。</td></tr></tbody></table><p>本说明采用固定规则读取当前方案，无在线大模型调用。</p>`)}
function forecast(){const isLoad=UI.forecast==='load',pred=isLoad?data.load:data.pv,actual=isLoad?data.actual:data.actualPV,err=Engine.error(pred,actual);return `${queryBar()}<section class="card"><div class="cardhead"><h3>负荷与光伏预测</h3><div class="actions"><span class="sub">负责人：韦佳伶</span>${btn('模块接口',"showEvidence('forecast')",'small')}${btn('进入调度',"go('dispatch')",'small primary')}</div></div><div class="tabline"><div class="tabs">${[['load','负荷预测'],['pv','光伏预测']].map(a=>`<button class="tab ${UI.forecast===a[0]?'active':''}" onclick="UI.forecast='${a[0]}';render()">${a[1]}</button>`).join('')}</div><span class="sub">发布时间：前一日18:00（模拟）　版本：DEMO-F1</span></div><div class="prediction-layout"><div class="hour-table"><table><thead><tr><th>时段</th><th>预测(kW)</th><th>参考(kW)</th><th>偏差(kW)</th></tr></thead><tbody>${pred.map((v,h)=>`<tr><td>${String(h).padStart(2,'0')}:00</td><td>${fmt(v,2)}</td><td>${fmt(actual[h],2)}</td><td>${fmt(v-actual[h],2)}</td></tr>`).join('')}</tbody></table></div><div class="prediction-chart">${chart([{name:isLoad?'负荷预测':'光伏预测',values:pred,color:colors.load},{name:'参考值（合成）',values:actual,color:colors.pv}],'kW',265)}<div class="kpis prediction-stats">${kpi('MAE',fmt(err.mae,2),'kW','平均绝对误差')}${kpi('RMSE',fmt(err.rmse,2),'kW','均方根误差')}${kpi('数据完整率','100','%','24/24个时段')}</div><div class="note-line">预测值与参考值均为合成序列，误差不代表真实预测模型的测试效果。</div></div></div></section>${panel('数据检查',`<div class="tablewrap"><table><thead><tr><th>检查项</th><th>要求</th><th>结果</th><th>说明</th></tr></thead><tbody><tr><td>时间窗口</td><td>分析日00:00—23:00</td><td>${badge('通过')}</td><td>Asia/Shanghai，1小时粒度</td></tr><tr><td>完整性与单位</td><td>24条记录，功率单位kW</td><td>${badge('通过')}</td><td>模拟输入无缺失值</td></tr><tr><td>模型接入</td><td>预测接口及版本</td><td>${badge('演示接口','warn')}</td><td>当前为规则合成器，正式模型待接入</td></tr></tbody></table></div>`)}`}
function parameters(){return `${queryBar()}<section class="card"><div class="cardhead"><h3>光储设备参数</h3><div class="actions"><span class="sub">负责人：凌俊楷</span>${btn('保存参数',"saveAssets()",'primary small')+btn('参数依据',"showEvidence('parameters')",'small')}${btn('进入调度',"go('dispatch')",'primary small')}</div></div><div class="tablewrap"><table class="asset-table"><thead><tr><th>设备名称</th><th>参数项</th><th>参数值</th><th>单位</th><th>设置依据</th></tr></thead><tbody><tr><td>光伏系统</td><td>装机容量</td><td>150</td><td>kWp</td><td>演示假设</td></tr><tr><td rowspan="5">储能系统</td><td><label for="cap">额定容量</label></td><td><input id="cap" aria-label="储能容量" type="number" min="100" max="1000" value="${S.capacity}"></td><td>kWh</td><td>可调整范围100—1000</td></tr><tr><td><label for="power">额定充放电功率</label></td><td><input id="power" type="number" min="20" max="100" value="${S.power}"></td><td>kW</td><td>可调整范围20—100</td></tr><tr><td>充电 / 放电效率</td><td>95 / 95</td><td>%</td><td>固定假设参数</td></tr><tr><td>SOC下限 / 上限</td><td>15 / 90</td><td>%</td><td>调度边界约束</td></tr><tr><td>初始SOC</td><td>50</td><td>%</td><td>正常状态末端恢复初始能量</td></tr></tbody></table></div></section><div class="grid2 equal">${panel('分时碳因子',chart([{name:'碳因子（合成）',values:data.carbon,color:colors.load}],'kgCO₂/kWh',210)+`<div class="note-line">版本DEMO-C1；仅核算购电碳排，不含全生命周期。</div>`)}${panel('分时电价',chart([{name:'电价（假设）',values:data.price,color:colors.pv}],'元/kWh',210)+`<div class="note-line">假设分时电价，不作为实际结算依据。</div>`)}</div>`}
const originalFault=fault;
fault=function(){return originalFault().replace(/<div class="notice">[\s\S]*?<\/div>/,'<div class="event-caption"><span>事件类型：储能支路断开</span><span>来源：预设仿真</span><span>发生时间：14:00</span><span>设备：BESS-01</span></div>')};
const originalReports=reports;
reports=function(){return originalReports().replace(teamCards(),'')};
function teamCards(){return ''}
function applyFilters(silent=false){
 const day=$('#day')?.value||S.date,weather=$('#weather')?.value||S.scenario,objective=$('#objective')?.value||S.objective;
 const budget=$('#budget')?Number($('#budget').value):S.budget;
 if(!Number.isFinite(budget)||budget<0||budget>30){toast('费用增幅上限应为0—30%');return false;}
 if(budget!==S.budget){S.budget=budget;S.dataVersion++;draft=Engine.plans(data,S);S.current=null;}
 if(day!==S.date||weather!==S.scenario){S.date=day;S.scenario=weather;S.dataVersion++;data=Engine.dataset(weather);draft=Engine.plans(data,S);S.current=null;S.fault=null;}
 if(objective!==S.objective){S.objective=objective;S.current=null;}
 render();if(!silent)toast('查询完成，共24个时段');return true;
}
function generateFromForm(){if(applyFilters(true))runPlan();}
function saveAssets(){
 const capacity=Number($('#cap').value),power=Number($('#power').value);
 if(!Number.isFinite(capacity)||capacity<100||capacity>1000||!Number.isFinite(power)||power<20||power>100){toast('容量应为100—1000 kWh，功率应为20—100 kW');return;}
 S.capacity=capacity;S.power=power;S.dataVersion++;S.current=null;S.fault=null;draft=Engine.plans(data,S);render();toast('参数已保存，请重新生成调度方案');
}
S.page='dispatch';render();
